import { Component, inject, signal, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { UserService } from '../../../../../services/user.service';
import { UserRole } from '../../../../../models/user.model';
import { extractErrorMessage } from '../../../../../shared/utils/error-utils';

@Component({
  selector: 'app-usuario-form',
  standalone: true,
  imports: [ReactiveFormsModule],
  templateUrl: './usuario-form.component.html',
})
export class UsuarioFormComponent implements OnInit {
  private readonly fb = inject(FormBuilder);
  private readonly userService = inject(UserService);
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  protected readonly isEditMode = signal(false);
  protected readonly userId = signal<number | null>(null);
  protected readonly loading = signal(false);
  protected readonly submitting = signal(false);
  protected readonly errorMessage = signal('');
  protected readonly showPasswordFields = signal(false);
  protected form!: FormGroup;

  ngOnInit(): void {
    this.initForm();
    const idParam = this.route.snapshot.paramMap.get('id');

    if (idParam) {
      this.isEditMode.set(true);
      this.userId.set(+idParam);
      this.loadUser(+idParam);
    } else {
      this.showPasswordFields.set(true);
      this.setupPasswordValidators();
    }
  }

  private initForm(): void {
    this.form = this.fb.group({
      name: ['', [Validators.required, Validators.maxLength(255)]],
      email: ['', [Validators.required, Validators.email, Validators.maxLength(255)]],
      role: ['ejecutivo', [Validators.required]],
      nivel_gobierno: ['estatal'],
      changePassword: [false],
      password: [''],
      password_confirmation: [''],
    });

    this.form.get('role')?.valueChanges.subscribe((role: UserRole) => {
      const nivelControl = this.form.get('nivel_gobierno');
      if (role === 'admin' || role === 'ejecutivo') {
        nivelControl?.setValidators([Validators.required]);
      } else {
        nivelControl?.clearValidators();
      }
      nivelControl?.updateValueAndValidity();
    });
  }

  protected toggleChangePassword(event: Event): void {
    const checked = (event.target as HTMLInputElement).checked;
    this.showPasswordFields.set(checked);
    if (checked) {
      this.setupPasswordValidators();
    } else {
      this.clearPasswordValidators();
    }
  }

  private setupPasswordValidators(): void {
    const passwordControl = this.form.get('password');
    const confirmControl = this.form.get('password_confirmation');
    passwordControl?.setValidators([Validators.required, Validators.minLength(8)]);
    confirmControl?.setValidators([Validators.required]);
    passwordControl?.updateValueAndValidity();
    confirmControl?.updateValueAndValidity();
  }

  private clearPasswordValidators(): void {
    const passwordControl = this.form.get('password');
    const confirmControl = this.form.get('password_confirmation');
    passwordControl?.clearValidators();
    confirmControl?.clearValidators();
    passwordControl?.setValue('');
    confirmControl?.setValue('');
    passwordControl?.updateValueAndValidity();
    confirmControl?.updateValueAndValidity();
  }

  private loadUser(id: number): void {
    this.loading.set(true);
    this.userService.getUser(id).subscribe({
      next: (user) => {
        this.form.patchValue({
          name: user.name,
          email: user.email,
          role: user.role,
          nivel_gobierno: user.nivelGobierno || user.nivel_gobierno || 'estatal',
        });
        this.loading.set(false);
      },
      error: (err) => {
        this.errorMessage.set(extractErrorMessage(err));
        this.loading.set(false);
      },
    });
  }

  protected onSubmit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    if (
      this.showPasswordFields() &&
      this.form.value.password !== this.form.value.password_confirmation
    ) {
      this.errorMessage.set('Las contraseñas no coinciden.');
      return;
    }

    this.submitting.set(true);
    this.errorMessage.set('');

    const payload = {
      name: this.form.value.name,
      email: this.form.value.email,
      role: this.form.value.role,
      nivel_gobierno: this.form.value.nivel_gobierno,
      ...(this.showPasswordFields()
        ? {
            password: this.form.value.password,
            password_confirmation: this.form.value.password_confirmation,
          }
        : {}),
    };

    if (this.isEditMode() && this.userId()) {
      this.userService.updateUser(this.userId()!, payload).subscribe({
        next: () => {
          this.submitting.set(false);
          this.router.navigate(['/ejecutivos/configuracion/usuarios']);
        },
        error: (err) => {
          this.submitting.set(false);
          this.errorMessage.set(extractErrorMessage(err));
        },
      });
    } else {
      this.userService.createUser(payload).subscribe({
        next: () => {
          this.submitting.set(false);
          this.router.navigate(['/ejecutivos/configuracion/usuarios']);
        },
        error: (err) => {
          this.submitting.set(false);
          this.errorMessage.set(extractErrorMessage(err));
        },
      });
    }
  }

  protected cancel(): void {
    this.router.navigate(['/ejecutivos/configuracion/usuarios']);
  }
}
